import React from "react";
import styled from "styled-components";

const CartContainer = styled.div`
    position: fixed;
    top: 0;
    right: 0;
    width: 400px;
    height: 100%;
    background-color: #fff;
    box-shadow: -2px 0 5px rgba(0, 0, 0, 0.1);
    transform: translateX(100%);
    transition: transform 0.3s ease-in-out;
    z-index: 1000;
    padding: 20px;
    overflow-y: auto;

    &.open {
        transform: translateX(0);
    }
`;

const CloseButton = styled.button`
    background-color: #f44336;
    color: white;
    border: none;
    padding: 10px 15px;
    cursor: pointer;
    font-size: 16px;
    margin-bottom: 20px;
    width: 100%;
    &:hover {
        background-color: #d32f2f;
    }
`;

const Cart = ({ cart, togleCart, removeFromCart }) => {
    const totalPrice = cart.reduce((total, product) => total + (+product.price), 0);
    return (
        <CartContainer className={cart.length > 0 ? "open" : ""}>
            <CloseButton onClick={togleCart}>Закрыть</CloseButton>
            <h2>Ваша корзина</h2>
            {cart.length === 0 ? (
                <p>Корзина пуста</p>
            ) : (
                <ul>
                    {cart.map((product) => (
                        <li key={product.id}>
                            <h3>{product.name}</h3>
                            <p>Цена: {product.price}</p>
                            <button onClick={() => removeFromCart(product.id)}>Удалить</button>
                        </li>
                    ))}
                </ul>
            )}
            <h3>Общая стоимость: {totalPrice} тг</h3>
        </CartContainer>
    );
};

export default Cart;
